// A compact backtracking regular expression engine.
//
// Supports the subset of PCRE syntax that the bundled log formats need:
// literals, '.', character classes, escape classes, groups (capturing,
// non-capturing and named), alternation, greedy/lazy quantifiers, anchors
// and inline case-insensitivity.
#pragma once

#include <map>
#include <memory>
#include <string>
#include <vector>

namespace re {

struct Match {
    bool matched = false;
    // begin/end offsets for each group; group 0 is the whole match.
    std::vector<int> begin;
    std::vector<int> end;

    bool has(int gi) const
    {
        return gi >= 0 && gi < (int) begin.size() && begin[gi] >= 0;
    }
    std::string str(const std::string& subject, int gi) const
    {
        if (!has(gi)) {
            return std::string();
        }
        return subject.substr(begin[gi], end[gi] - begin[gi]);
    }
};

class Node;
using NodePtr = std::shared_ptr<Node>;

class Regex {
public:
    Regex() = default;
    explicit Regex(const std::string& pattern);

    bool ok() const { return this->r_root != nullptr; }
    const std::string& error() const { return this->r_error; }
    const std::string& pattern() const { return this->r_pattern; }

    int group_count() const { return this->r_group_count; }
    int group_index(const std::string& name) const;
    const std::vector<std::string>& group_names() const
    {
        return this->r_group_names;
    }

    // Anchored at 'start'; returns the leftmost match at or after 'start'.
    Match search(const std::string& subject, int start = 0) const;
    bool matches(const std::string& subject) const
    {
        return this->search(subject).matched;
    }

private:
    std::string r_pattern;
    std::string r_error;
    NodePtr r_root;
    int r_group_count = 1;
    std::vector<std::string> r_group_names;
    std::map<std::string, int> r_named;

    friend class Parser;
};

// Escape the regex meta characters in 'lit'.
std::string quote(const std::string& lit);

}  // namespace re

