#include "re.h"

#include <bitset>
#include <cctype>
#include <cstring>
#include <functional>

namespace re {

using Cont = std::function<bool(int)>;

struct Ctx {
    const std::string* subject;
    std::vector<int>* beg;
    std::vector<int>* end;
    long steps = 0;
};

class Node {
public:
    virtual ~Node() = default;
    virtual bool m(Ctx& ctx, int pos, const Cont& k) const = 0;
};

namespace {

class CharSet : public Node {
public:
    std::bitset<256> cs_set;
    bool cs_fold = false;

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        const std::string& s = *ctx.subject;
        if (pos >= (int) s.size()) {
            return false;
        }
        auto ch = (unsigned char) s[pos];
        if (!this->cs_set[ch]) {
            if (!this->cs_fold) {
                return false;
            }
            auto alt = (unsigned char) (isupper(ch) ? tolower(ch)
                                                    : toupper(ch));
            if (alt == ch || !this->cs_set[alt]) {
                return false;
            }
        }
        return k(pos + 1);
    }
};

class Literal : public Node {
public:
    std::string l_text;
    bool l_fold = false;

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        const std::string& s = *ctx.subject;
        auto len = (int) this->l_text.size();
        if (pos + len > (int) s.size()) {
            return false;
        }
        if (this->l_fold) {
            for (int lpc = 0; lpc < len; lpc++) {
                if (tolower((unsigned char) s[pos + lpc])
                    != tolower((unsigned char) this->l_text[lpc]))
                {
                    return false;
                }
            }
        } else if (memcmp(s.data() + pos, this->l_text.data(), len) != 0) {
            return false;
        }
        return k(pos + len);
    }
};

class Concat : public Node {
public:
    std::vector<NodePtr> c_kids;

    bool step(Ctx& ctx, size_t idx, int pos, const Cont& k) const
    {
        if (idx == this->c_kids.size()) {
            return k(pos);
        }
        return this->c_kids[idx]->m(ctx, pos, [&, idx](int np) {
            return this->step(ctx, idx + 1, np, k);
        });
    }

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        return this->step(ctx, 0, pos, k);
    }
};

class Alt : public Node {
public:
    std::vector<NodePtr> a_kids;

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        for (const auto& kid : this->a_kids) {
            if (kid->m(ctx, pos, k)) {
                return true;
            }
        }
        return false;
    }
};

class Repeat : public Node {
public:
    NodePtr r_kid;
    int r_min = 0;
    int r_max = -1;
    bool r_greedy = true;

    bool rep(Ctx& ctx, int count, int pos, const Cont& k) const
    {
        if (++ctx.steps > 4000000) {
            return false;
        }
        bool can_more = (this->r_max < 0 || count < this->r_max);
        auto more = [&]() {
            if (!can_more) {
                return false;
            }
            return this->r_kid->m(ctx, pos, [&](int np) {
                if (np == pos && count >= this->r_min) {
                    // Zero-width repetition; stop to avoid looping forever.
                    return false;
                }
                return this->rep(ctx, count + 1, np, k);
            });
        };

        if (count < this->r_min) {
            return more();
        }
        if (this->r_greedy) {
            return more() || k(pos);
        }
        return k(pos) || more();
    }

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        return this->rep(ctx, 0, pos, k);
    }
};

class Group : public Node {
public:
    NodePtr g_kid;
    int g_index = -1;

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        if (this->g_index < 0) {
            return this->g_kid->m(ctx, pos, k);
        }
        int saved_b = (*ctx.beg)[this->g_index];
        int saved_e = (*ctx.end)[this->g_index];
        bool res = this->g_kid->m(ctx, pos, [&](int np) {
            int pb = (*ctx.beg)[this->g_index];
            int pe = (*ctx.end)[this->g_index];
            (*ctx.beg)[this->g_index] = pos;
            (*ctx.end)[this->g_index] = np;
            if (k(np)) {
                return true;
            }
            (*ctx.beg)[this->g_index] = pb;
            (*ctx.end)[this->g_index] = pe;
            return false;
        });
        if (!res) {
            (*ctx.beg)[this->g_index] = saved_b;
            (*ctx.end)[this->g_index] = saved_e;
        }
        return res;
    }
};

class Anchor : public Node {
public:
    // 0 = ^, 1 = $, 2 = \b, 3 = \B, 4 = \A, 5 = \z
    int a_kind = 0;

    static bool is_word(const std::string& s, int pos)
    {
        if (pos < 0 || pos >= (int) s.size()) {
            return false;
        }
        auto ch = (unsigned char) s[pos];
        return isalnum(ch) || ch == '_';
    }

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        const std::string& s = *ctx.subject;
        switch (this->a_kind) {
            case 0:
                if (pos != 0) {
                    return false;
                }
                break;
            case 1:
                if (pos != (int) s.size()) {
                    return false;
                }
                break;
            case 2:
                if (is_word(s, pos - 1) == is_word(s, pos)) {
                    return false;
                }
                break;
            case 3:
                if (is_word(s, pos - 1) != is_word(s, pos)) {
                    return false;
                }
                break;
            case 4:
                if (pos != 0) {
                    return false;
                }
                break;
            default:
                if (pos != (int) s.size()) {
                    return false;
                }
                break;
        }
        return k(pos);
    }
};

class Look : public Node {
public:
    NodePtr lk_kid;
    bool lk_ahead = true;
    bool lk_negate = false;
    int lk_width = 0;  // for lookbehind: fixed width of the sub-pattern

    bool m(Ctx& ctx, int pos, const Cont& k) const override
    {
        bool hit;
        if (this->lk_ahead) {
            hit = this->lk_kid->m(ctx, pos, [](int) { return true; });
        } else {
            int start = pos - this->lk_width;
            hit = start >= 0
                && this->lk_kid->m(
                    ctx, start, [&](int np) { return np == pos; });
        }
        if (hit == this->lk_negate) {
            return false;
        }
        return k(pos);
    }
};

void
add_class(std::bitset<256>& set, char cls)
{
    for (int ch = 0; ch < 256; ch++) {
        bool hit = false;
        switch (cls) {
            case 'd':
                hit = isdigit(ch) != 0;
                break;
            case 'w':
                hit = isalnum(ch) != 0 || ch == '_';
                break;
            case 's':
                hit = (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r'
                       || ch == '\f' || ch == '\v');
                break;
            case 'h':
                hit = (ch == ' ' || ch == '\t');
                break;
            default:
                break;
        }
        if (hit) {
            set[ch] = true;
        }
    }
}

}  // namespace

class Parser {
public:
    Parser(Regex& rx, const std::string& pat) : p_rx(rx), p_pat(pat) {}

    NodePtr parse()
    {
        auto node = this->alternation();
        if (this->p_pos != this->p_pat.size() && this->p_err.empty()) {
            this->p_err = "unexpected ')'";
        }
        if (!this->p_err.empty()) {
            return nullptr;
        }
        return node;
    }

    std::string error() const { return this->p_err; }

private:
    Regex& p_rx;
    const std::string& p_pat;
    size_t p_pos = 0;
    std::string p_err;
    bool p_fold = false;

    bool eof() const { return this->p_pos >= this->p_pat.size(); }
    char peek() const { return this->p_pat[this->p_pos]; }

    NodePtr alternation()
    {
        std::vector<NodePtr> branches;
        branches.push_back(this->sequence());
        while (!this->eof() && this->peek() == '|') {
            this->p_pos += 1;
            branches.push_back(this->sequence());
        }
        if (branches.size() == 1) {
            return branches[0];
        }
        auto alt = std::make_shared<Alt>();
        alt->a_kids = branches;
        return alt;
    }

    NodePtr sequence()
    {
        auto cat = std::make_shared<Concat>();
        while (!this->eof() && this->peek() != '|' && this->peek() != ')') {
            auto atom = this->quantified();
            if (atom == nullptr) {
                break;
            }
            cat->c_kids.push_back(atom);
        }
        if (cat->c_kids.size() == 1) {
            return cat->c_kids[0];
        }
        return cat;
    }

    NodePtr quantified()
    {
        auto atom = this->single();
        if (atom == nullptr) {
            return nullptr;
        }
        while (!this->eof()) {
            int min = -1;
            int max = -1;
            char ch = this->peek();
            if (ch == '*') {
                min = 0;
                max = -1;
                this->p_pos += 1;
            } else if (ch == '+') {
                min = 1;
                max = -1;
                this->p_pos += 1;
            } else if (ch == '?') {
                min = 0;
                max = 1;
                this->p_pos += 1;
            } else if (ch == '{') {
                size_t save = this->p_pos;
                this->p_pos += 1;
                std::string lo, hi;
                while (!this->eof() && isdigit((unsigned char) this->peek())) {
                    lo.push_back(this->p_pat[this->p_pos++]);
                }
                bool comma = false;
                if (!this->eof() && this->peek() == ',') {
                    comma = true;
                    this->p_pos += 1;
                    while (!this->eof()
                           && isdigit((unsigned char) this->peek()))
                    {
                        hi.push_back(this->p_pat[this->p_pos++]);
                    }
                }
                if (this->eof() || this->peek() != '}' || lo.empty()) {
                    this->p_pos = save;
                    break;
                }
                this->p_pos += 1;
                min = std::stoi(lo);
                max = comma ? (hi.empty() ? -1 : std::stoi(hi)) : min;
            } else {
                break;
            }

            auto rep = std::make_shared<Repeat>();
            rep->r_kid = atom;
            rep->r_min = min;
            rep->r_max = max;
            if (!this->eof() && (this->peek() == '?' || this->peek() == '+')) {
                rep->r_greedy = (this->peek() == '+');
                this->p_pos += 1;
            }
            atom = rep;
        }
        return atom;
    }

    NodePtr make_set(const std::bitset<256>& bits)
    {
        auto cs = std::make_shared<CharSet>();
        cs->cs_set = bits;
        cs->cs_fold = this->p_fold;
        return cs;
    }

    NodePtr single()
    {
        if (this->eof()) {
            return nullptr;
        }
        char ch = this->p_pat[this->p_pos];
        switch (ch) {
            case '^': {
                this->p_pos += 1;
                auto a = std::make_shared<Anchor>();
                a->a_kind = 0;
                return a;
            }
            case '$': {
                this->p_pos += 1;
                auto a = std::make_shared<Anchor>();
                a->a_kind = 1;
                return a;
            }
            case '.': {
                this->p_pos += 1;
                std::bitset<256> bits;
                bits.set();
                bits['\n'] = false;
                return this->make_set(bits);
            }
            case '[':
                return this->char_class();
            case '(':
                return this->group();
            case '\\':
                return this->escape();
            default: {
                this->p_pos += 1;
                auto lit = std::make_shared<Literal>();
                lit->l_text.push_back(ch);
                lit->l_fold = this->p_fold;
                return lit;
            }
        }
    }

    NodePtr group()
    {
        this->p_pos += 1;  // '('
        int index = -1;
        bool look = false;
        bool ahead = true;
        bool negate = false;

        if (!this->eof() && this->peek() == '?') {
            this->p_pos += 1;
            if (this->eof()) {
                this->p_err = "truncated group";
                return nullptr;
            }
            char kind = this->peek();
            if (kind == ':') {
                this->p_pos += 1;
            } else if (kind == '=' || kind == '!') {
                this->p_pos += 1;
                look = true;
                negate = (kind == '!');
            } else if (kind == '<'
                       && this->p_pos + 1 < this->p_pat.size()
                       && (this->p_pat[this->p_pos + 1] == '='
                           || this->p_pat[this->p_pos + 1] == '!'))
            {
                negate = (this->p_pat[this->p_pos + 1] == '!');
                this->p_pos += 2;
                look = true;
                ahead = false;
            } else if (kind == '<' || kind == 'P' || kind == '\'') {
                if (kind == 'P') {
                    this->p_pos += 1;
                }
                char close = (this->peek() == '\'') ? '\'' : '>';
                this->p_pos += 1;
                std::string name;
                while (!this->eof() && this->peek() != close) {
                    name.push_back(this->p_pat[this->p_pos++]);
                }
                if (this->eof()) {
                    this->p_err = "unterminated group name";
                    return nullptr;
                }
                this->p_pos += 1;
                index = this->p_rx.r_group_count++;
                this->p_rx.r_group_names.resize(this->p_rx.r_group_count);
                this->p_rx.r_group_names[index] = name;
                this->p_rx.r_named[name] = index;
            } else if (kind == '#') {
                while (!this->eof() && this->peek() != ')') {
                    this->p_pos += 1;
                }
                if (!this->eof()) {
                    this->p_pos += 1;
                }
                auto cat = std::make_shared<Concat>();
                return cat;
            } else {
                // Inline flag settings, e.g. (?i) or (?i:...)
                bool fold = this->p_fold;
                while (!this->eof() && this->peek() != ')'
                       && this->peek() != ':')
                {
                    if (this->peek() == 'i') {
                        fold = true;
                    }
                    this->p_pos += 1;
                }
                if (this->eof()) {
                    this->p_err = "truncated flags";
                    return nullptr;
                }
                if (this->peek() == ')') {
                    this->p_pos += 1;
                    this->p_fold = fold;
                    return std::make_shared<Concat>();
                }
                this->p_pos += 1;
                bool saved = this->p_fold;
                this->p_fold = fold;
                auto kid = this->alternation();
                this->p_fold = saved;
                if (this->eof() || this->peek() != ')') {
                    this->p_err = "missing ')'";
                    return nullptr;
                }
                this->p_pos += 1;
                auto grp = std::make_shared<Group>();
                grp->g_kid = kid;
                return grp;
            }
        } else {
            index = this->p_rx.r_group_count++;
            this->p_rx.r_group_names.resize(this->p_rx.r_group_count);
        }

        bool saved_fold = this->p_fold;
        auto kid = this->alternation();
        this->p_fold = saved_fold;
        if (this->eof() || this->peek() != ')') {
            this->p_err = "missing ')'";
            return nullptr;
        }
        this->p_pos += 1;

        if (look) {
            auto lk = std::make_shared<Look>();
            lk->lk_kid = kid;
            lk->lk_ahead = ahead;
            lk->lk_negate = negate;
            lk->lk_width = ahead ? 0 : fixed_width(kid);
            return lk;
        }
        auto grp = std::make_shared<Group>();
        grp->g_kid = kid;
        grp->g_index = index;
        return grp;
    }

    // Lookbehind needs a fixed width; compute it where possible.
    static int fixed_width(const NodePtr& node)
    {
        if (auto lit = dynamic_cast<Literal*>(node.get())) {
            return (int) lit->l_text.size();
        }
        if (dynamic_cast<CharSet*>(node.get()) != nullptr) {
            return 1;
        }
        if (auto cat = dynamic_cast<Concat*>(node.get())) {
            int total = 0;
            for (const auto& kid : cat->c_kids) {
                total += fixed_width(kid);
            }
            return total;
        }
        if (auto grp = dynamic_cast<Group*>(node.get())) {
            return fixed_width(grp->g_kid);
        }
        if (auto alt = dynamic_cast<Alt*>(node.get())) {
            return alt->a_kids.empty() ? 0 : fixed_width(alt->a_kids[0]);
        }
        if (auto rep = dynamic_cast<Repeat*>(node.get())) {
            return fixed_width(rep->r_kid) * (rep->r_min > 0 ? rep->r_min : 0);
        }
        return 0;
    }

    NodePtr char_class()
    {
        this->p_pos += 1;  // '['
        std::bitset<256> bits;
        bool negate = false;
        if (!this->eof() && this->peek() == '^') {
            negate = true;
            this->p_pos += 1;
        }
        bool first = true;
        while (!this->eof() && (this->peek() != ']' || first)) {
            first = false;
            if (this->p_pat.compare(this->p_pos, 2, "[:") == 0) {
                auto close = this->p_pat.find(":]", this->p_pos);
                if (close != std::string::npos) {
                    auto name
                        = this->p_pat.substr(this->p_pos + 2,
                                             close - this->p_pos - 2);
                    for (int ch = 0; ch < 256; ch++) {
                        bool hit = false;
                        if (name == "alpha") {
                            hit = isalpha(ch);
                        } else if (name == "digit") {
                            hit = isdigit(ch);
                        } else if (name == "alnum") {
                            hit = isalnum(ch);
                        } else if (name == "space") {
                            hit = isspace(ch);
                        } else if (name == "upper") {
                            hit = isupper(ch);
                        } else if (name == "lower") {
                            hit = islower(ch);
                        } else if (name == "punct") {
                            hit = ispunct(ch);
                        } else if (name == "xdigit") {
                            hit = isxdigit(ch);
                        } else if (name == "print") {
                            hit = isprint(ch);
                        } else if (name == "graph") {
                            hit = isgraph(ch);
                        }
                        if (hit) {
                            bits[ch] = true;
                        }
                    }
                    this->p_pos = close + 2;
                    continue;
                }
            }

            int lo = this->class_char(bits);
            if (lo < 0) {
                continue;
            }
            if (this->p_pos + 1 < this->p_pat.size() && this->peek() == '-'
                && this->p_pat[this->p_pos + 1] != ']')
            {
                this->p_pos += 1;
                std::bitset<256> ignore;
                int hi = this->class_char(ignore);
                if (hi < 0) {
                    hi = lo;
                }
                for (int ch = lo; ch <= hi; ch++) {
                    bits[ch] = true;
                }
            } else {
                bits[lo] = true;
            }
        }
        if (!this->eof()) {
            this->p_pos += 1;  // ']'
        }
        if (negate) {
            bits.flip();
        }
        return this->make_set(bits);
    }

    // Returns the literal char, or -1 when a whole class was added to 'bits'.
    int class_char(std::bitset<256>& bits)
    {
        char ch = this->p_pat[this->p_pos++];
        if (ch != '\\') {
            return (unsigned char) ch;
        }
        if (this->eof()) {
            return '\\';
        }
        char esc = this->p_pat[this->p_pos++];
        switch (esc) {
            case 'd':
            case 'w':
            case 's':
            case 'h':
                add_class(bits, esc);
                return -1;
            case 'D':
            case 'W':
            case 'S': {
                std::bitset<256> tmp;
                add_class(tmp, tolower(esc));
                tmp.flip();
                bits |= tmp;
                return -1;
            }
            case 'n':
                return '\n';
            case 't':
                return '\t';
            case 'r':
                return '\r';
            case 'f':
                return '\f';
            case 'v':
                return '\v';
            case '0':
                return '\0';
            case 'e':
                return 0x1b;
            case 'a':
                return '\a';
            case 'x': {
                std::string hex;
                while (!this->eof() && hex.size() < 2
                       && isxdigit((unsigned char) this->peek()))
                {
                    hex.push_back(this->p_pat[this->p_pos++]);
                }
                return hex.empty() ? 'x' : (int) strtol(hex.c_str(), nullptr, 16);
            }
            default:
                return (unsigned char) esc;
        }
    }

    NodePtr escape()
    {
        this->p_pos += 1;  // backslash
        if (this->eof()) {
            auto lit = std::make_shared<Literal>();
            lit->l_text = "\\";
            return lit;
        }
        char esc = this->p_pat[this->p_pos++];
        switch (esc) {
            case 'd':
            case 'w':
            case 's':
            case 'h': {
                std::bitset<256> bits;
                add_class(bits, esc);
                return this->make_set(bits);
            }
            case 'D':
            case 'W':
            case 'S': {
                std::bitset<256> bits;
                add_class(bits, tolower(esc));
                bits.flip();
                return this->make_set(bits);
            }
            case 'b':
            case 'B':
            case 'A':
            case 'z':
            case 'Z': {
                auto a = std::make_shared<Anchor>();
                a->a_kind = (esc == 'b')   ? 2
                    : (esc == 'B')         ? 3
                    : (esc == 'A')         ? 4
                                           : 5;
                return a;
            }
            default: {
                this->p_pos -= 1;
                std::bitset<256> bits;
                int ch = this->class_char(bits);
                if (ch < 0) {
                    return this->make_set(bits);
                }
                auto lit = std::make_shared<Literal>();
                lit->l_text.push_back((char) ch);
                lit->l_fold = this->p_fold;
                return lit;
            }
        }
    }
};

Regex::Regex(const std::string& pattern) : r_pattern(pattern)
{
    this->r_group_names.resize(1);
    Parser parser(*this, this->r_pattern);
    auto root = parser.parse();
    if (root == nullptr) {
        this->r_error = parser.error();
        if (this->r_error.empty()) {
            this->r_error = "invalid pattern";
        }
        return;
    }
    this->r_root = root;
}

int
Regex::group_index(const std::string& name) const
{
    auto iter = this->r_named.find(name);
    if (iter == this->r_named.end()) {
        return -1;
    }
    return iter->second;
}

Match
Regex::search(const std::string& subject, int start) const
{
    Match retval;
    if (this->r_root == nullptr) {
        return retval;
    }
    retval.begin.assign(this->r_group_count, -1);
    retval.end.assign(this->r_group_count, -1);

    for (int pos = start; pos <= (int) subject.size(); pos++) {
        Ctx ctx;
        ctx.subject = &subject;
        ctx.beg = &retval.begin;
        ctx.end = &retval.end;
        int stop = -1;
        bool hit = this->r_root->m(ctx, pos, [&stop](int np) {
            stop = np;
            return true;
        });
        if (hit) {
            retval.matched = true;
            retval.begin[0] = pos;
            retval.end[0] = stop;
            return retval;
        }
        retval.begin.assign(this->r_group_count, -1);
        retval.end.assign(this->r_group_count, -1);
    }
    return retval;
}

std::string
quote(const std::string& lit)
{
    static const std::string META = "\\^$.[]|()?*+{}-";
    std::string retval;
    for (char ch : lit) {
        if (META.find(ch) != std::string::npos) {
            retval.push_back('\\');
        }
        retval.push_back(ch);
    }
    return retval;
}

}  // namespace re

