#include "util.h"

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <sys/stat.h>
#include <unistd.h>

namespace util {

std::vector<std::string>
split(const std::string& str, char sep)
{
    std::vector<std::string> retval;
    size_t start = 0;
    while (true) {
        auto pos = str.find(sep, start);
        if (pos == std::string::npos) {
            retval.push_back(str.substr(start));
            break;
        }
        retval.push_back(str.substr(start, pos - start));
        start = pos + 1;
    }
    return retval;
}

std::string
join(const std::vector<std::string>& parts, const std::string& sep)
{
    std::string retval;
    for (size_t lpc = 0; lpc < parts.size(); lpc++) {
        if (lpc > 0) {
            retval += sep;
        }
        retval += parts[lpc];
    }
    return retval;
}

std::string
trim(const std::string& str)
{
    size_t start = 0;
    size_t stop = str.size();
    while (start < stop && isspace((unsigned char) str[start])) {
        start += 1;
    }
    while (stop > start && isspace((unsigned char) str[stop - 1])) {
        stop -= 1;
    }
    return str.substr(start, stop - start);
}

std::string
rtrim(const std::string& str)
{
    size_t stop = str.size();
    while (stop > 0 && isspace((unsigned char) str[stop - 1])) {
        stop -= 1;
    }
    return str.substr(0, stop);
}

bool
startswith(const std::string& str, const std::string& prefix)
{
    return str.size() >= prefix.size()
        && str.compare(0, prefix.size(), prefix) == 0;
}

bool
endswith(const std::string& str, const std::string& suffix)
{
    return str.size() >= suffix.size()
        && str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
}

std::string
to_lower(const std::string& str)
{
    std::string retval = str;
    for (auto& ch : retval) {
        ch = (char) tolower((unsigned char) ch);
    }
    return retval;
}

std::string
to_upper(const std::string& str)
{
    std::string retval = str;
    for (auto& ch : retval) {
        ch = (char) toupper((unsigned char) ch);
    }
    return retval;
}

std::string
sanitize(const std::string& line)
{
    std::string retval;
    retval.reserve(line.size());
    for (size_t lpc = 0; lpc < line.size(); lpc++) {
        auto ch = (unsigned char) line[lpc];
        if (ch == 0x1b) {
            // CSI / OSC / simple escape sequences are dropped entirely.
            if (lpc + 1 < line.size() && line[lpc + 1] == '[') {
                size_t end = lpc + 2;
                while (end < line.size()
                       && !(line[end] >= '@' && line[end] <= '~'))
                {
                    end += 1;
                }
                lpc = end;
            } else if (lpc + 1 < line.size() && line[lpc + 1] == ']') {
                size_t end = lpc + 2;
                while (end < line.size() && line[end] != '\a'
                       && line[end] != 0x1b)
                {
                    end += 1;
                }
                if (end < line.size() && line[end] == 0x1b) {
                    end += 1;
                }
                lpc = end;
            } else {
                lpc += 1;
            }
            continue;
        }
        if (ch == '\t') {
            retval.push_back('\t');
            continue;
        }
        if (ch < 0x20 || ch == 0x7f) {
            continue;
        }
        retval.push_back((char) ch);
    }
    return retval;
}

bool
is_valid_utf8(const std::string& data)
{
    size_t lpc = 0;
    while (lpc < data.size()) {
        auto ch = (unsigned char) data[lpc];
        if (ch == 0) {
            return false;
        }
        int extra;
        if (ch < 0x80) {
            extra = 0;
        } else if ((ch & 0xe0) == 0xc0) {
            extra = 1;
        } else if ((ch & 0xf0) == 0xe0) {
            extra = 2;
        } else if ((ch & 0xf8) == 0xf0) {
            extra = 3;
        } else {
            return false;
        }
        if (lpc + extra >= data.size() + (extra ? 0 : 1)) {
            if (lpc + extra >= data.size()) {
                return false;
            }
        }
        for (int idx = 1; idx <= extra; idx++) {
            if (((unsigned char) data[lpc + idx] & 0xc0) != 0x80) {
                return false;
            }
        }
        lpc += extra + 1;
    }
    return true;
}

size_t
display_width(const std::string& str)
{
    size_t retval = 0;
    for (size_t lpc = 0; lpc < str.size();) {
        auto ch = (unsigned char) str[lpc];
        if (ch < 0x80) {
            lpc += 1;
        } else if ((ch & 0xe0) == 0xc0) {
            lpc += 2;
        } else if ((ch & 0xf0) == 0xe0) {
            lpc += 3;
        } else if ((ch & 0xf8) == 0xf0) {
            lpc += 4;
        } else {
            lpc += 1;
        }
        retval += 1;
    }
    return retval;
}

std::string
pad_right(const std::string& str, size_t width)
{
    auto len = display_width(str);
    if (len >= width) {
        return str;
    }
    return str + std::string(width - len, ' ');
}

std::string
pad_left(const std::string& str, size_t width)
{
    auto len = display_width(str);
    if (len >= width) {
        return str;
    }
    return std::string(width - len, ' ') + str;
}

std::string
center(const std::string& str, size_t width)
{
    auto len = display_width(str);
    if (len >= width) {
        return str;
    }
    size_t left = (width - len) / 2;
    return std::string(left, ' ') + str + std::string(width - len - left, ' ');
}

std::string
read_file(const std::string& path, bool* ok)
{
    std::string retval;
    FILE* file = fopen(path.c_str(), "rb");
    if (file == nullptr) {
        if (ok != nullptr) {
            *ok = false;
        }
        return retval;
    }
    char buf[65536];
    size_t rc;
    while ((rc = fread(buf, 1, sizeof(buf), file)) > 0) {
        retval.append(buf, rc);
    }
    fclose(file);
    if (ok != nullptr) {
        *ok = true;
    }
    return retval;
}

bool
is_dir(const std::string& path)
{
    struct stat st;
    return stat(path.c_str(), &st) == 0 && S_ISDIR(st.st_mode);
}

bool
exists(const std::string& path)
{
    struct stat st;
    return stat(path.c_str(), &st) == 0;
}

std::string
abspath(const std::string& path)
{
    if (!path.empty() && path[0] == '/') {
        // Normalize away any '.' and '..' components.
        auto parts = split(path, '/');
        std::vector<std::string> stack;
        for (const auto& part : parts) {
            if (part.empty() || part == ".") {
                continue;
            }
            if (part == "..") {
                if (!stack.empty()) {
                    stack.pop_back();
                }
                continue;
            }
            stack.push_back(part);
        }
        return "/" + join(stack, "/");
    }
    char cwd[4096];
    if (getcwd(cwd, sizeof(cwd)) == nullptr) {
        return path;
    }
    return abspath(std::string(cwd) + "/" + path);
