std::string
trim(const std::string& str)
{
    size_t start = 0;
    size_t stop = str.size();
    while (start < stop && isspace((unsigned char) str[start])) {
        start += 1;
    }
    while (stop > start && isspace((unsigned char) str[stop - 1])) {
        stop -= 1;
    }
    return str.substr(start, stop - start);
}

std::string
rtrim(const std::string& str)
{
    size_t stop = str.size();
    while (stop > 0 && isspace((unsigned char) str[stop - 1])) {
        stop -= 1;
    }
    return str.substr(0, stop);
}

bool
startswith(const std::string& str, const std::string& prefix)
{
    return str.size() >= prefix.size()
        && str.compare(0, prefix.size(), prefix) == 0;
}

bool
endswith(const std::string& str, const std::string& suffix)
{
    return str.size() >= suffix.size()
        && str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
}

std::string
