}

std::string
sanitize(const std::string& line)
{
    std::string retval;
    retval.reserve(line.size());
    for (size_t lpc = 0; lpc < line.size(); lpc++) {
        auto ch = (unsigned char) line[lpc];
        if (ch == 0x1b) {
            // CSI / OSC / simple escape sequences are dropped entirely.
            if (lpc + 1 < line.size() && line[lpc + 1] == '[') {
                size_t end = lpc + 2;
                while (end < line.size()
                       && !(line[end] >= '@' && line[end] <= '~'))
                {
