bool
is_valid_utf8(const std::string& data)
{
    size_t lpc = 0;
    while (lpc < data.size()) {
        auto ch = (unsigned char) data[lpc];
        if (ch == 0) {
            return false;
        }
        int extra;
        if (ch < 0x80) {
            extra = 0;
        } else if ((ch & 0xe0) == 0xc0) {
            extra = 1;
        } else if ((ch & 0xf0) == 0xe0) {
            extra = 2;
        } else if ((ch & 0xf8) == 0xf0) {
            extra = 3;
        } else {
            return false;
        }
        if (lpc + extra >= data.size() + (extra ? 0 : 1)) {
            if (lpc + extra >= data.size()) {
                return false;
            }
        }
        for (int idx = 1; idx <= extra; idx++) {
            if (((unsigned char) data[lpc + idx] & 0xc0) != 0x80) {
                return false;
            }
        }
        lpc += extra + 1;
    }
    return true;
}

size_t
display_width(const std::string& str)
{
    size_t retval = 0;
    for (size_t lpc = 0; lpc < str.size();) {
        auto ch = (unsigned char) str[lpc];
        if (ch < 0x80) {
            lpc += 1;
        } else if ((ch & 0xe0) == 0xc0) {
            lpc += 2;
        } else if ((ch & 0xf0) == 0xe0) {
            lpc += 3;
        } else if ((ch & 0xf8) == 0xf0) {
            lpc += 4;
        } else {
            lpc += 1;
        }
        retval += 1;
    }
    return retval;
}

std::string
pad_right(const std::string& str, size_t width)
{
    auto len = display_width(str);
    if (len >= width) {
        return str;
    }
    return str + std::string(width - len, ' ');
}

std::string
pad_left(const std::string& str, size_t width)
{
    auto len = display_width(str);
    if (len >= width) {
        return str;
    }
    return std::string(width - len, ' ') + str;
}

std::string
center(const std::string& str, size_t width)
{
    auto len = display_width(str);
    if (len >= width) {
        return str;
    }
    size_t left = (width - len) / 2;
    return std::string(left, ' ') + str + std::string(width - len - left, ' ');
}

std::string
read_file(const std::string& path, bool* ok)
{
    std::string retval;
    FILE* file = fopen(path.c_str(), "rb");
    if (file == nullptr) {
