                             "may",
                             "june",
                             "july",
                             "august",
                             "september",
                             "october",
                             "november",
                             "december"};
const char* DAYS[] = {"sun", "mon", "tue", "wed", "thu", "fri", "sat"};

bool
read_int(const std::string& str, size_t& pos, int min_digits, int max_digits,
         int& out)
{
    int count = 0;
    int val = 0;
    while (pos < str.size() && count < max_digits
           && isdigit((unsigned char) str[pos]))
    {
        val = val * 10 + (str[pos] - '0');
        pos += 1;
        count += 1;
    }
    if (count < min_digits) {
        return false;
    }
    out = val;
    return true;
}

bool
match_word(const std::string& str, size_t& pos, const char* word)
{
    size_t len = strlen(word);
    if (pos + len > str.size()) {
        return false;
    }
    for (size_t lpc = 0; lpc < len; lpc++) {
        if (tolower((unsigned char) str[pos + lpc]) != word[lpc]) {
            return false;
        }
    }
    pos += len;
    return true;
}

// The ordered list of timestamp layouts, most specific first.
const char* FORMATS[] = {
    "%Y-%m-%dT%H:%M:%S.%f%z",
    "%Y-%m-%dT%H:%M:%S,%f%z",
    "%Y-%m-%dT%H:%M:%S%z",
