}  // namespace

int64_t
days_from_civil(int year, int month, int day)
{
    year -= month <= 2;
    int64_t era = (year >= 0 ? year : year - 399) / 400;
    auto yoe = (unsigned) (year - era * 400);
    unsigned doy = (153 * (month + (month > 2 ? -3 : 9)) + 2) / 5 + day - 1;
    unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + (int64_t) doe - 719468;
}

Parsed
scan_format(const std::string& str, size_t offset, const char* fmt,
            int base_year)
{
    Parsed retval;
    size_t pos = offset;
    int pm = -1;
    int frac_digits = 0;

    for (const char* fp = fmt; *fp != '\0'; fp++) {
        if (*fp != '%') {
            if (*fp == ' ') {
                // A literal space matches one or more spaces.
                if (pos >= str.size() || str[pos] != ' ') {
                    return retval;
                }
                while (pos < str.size() && str[pos] == ' ') {
                    pos += 1;
                }
                continue;
            }
            if (pos >= str.size() || str[pos] != *fp) {
                return retval;
            }
            pos += 1;
            continue;
        }
        fp += 1;
        switch (*fp) {
            case 'Y': {
                int val;
                if (!read_int(str, pos, 4, 4, val)) {
                    return retval;
                }
                retval.year = val;
                break;
            }
            case 'y': {
                int val;
                if (!read_int(str, pos, 2, 2, val)) {
                    return retval;
                }
                retval.year = val < 70 ? 2000 + val : 1900 + val;
                break;
            }
            case 'm': {
                int val;
                if (!read_int(str, pos, 1, 2, val)) {
                    return retval;
                }
                if (val < 1 || val > 12) {
                    return retval;
                }
                retval.month = val;
                break;
            }
            case 'd': {
                int val;
                if (!read_int(str, pos, 1, 2, val)) {
                    return retval;
                }
                if (val < 1 || val > 31) {
                    return retval;
                }
                retval.day = val;
                break;
            }
            case 'e': {
                while (pos < str.size() && str[pos] == ' ') {
                    pos += 1;
                }
                int val;
                if (!read_int(str, pos, 1, 2, val)) {
                    return retval;
                }
                if (val < 1 || val > 31) {
                    return retval;
                }
                retval.day = val;
                break;
            }
            case 'H': {
                int val;
                if (!read_int(str, pos, 1, 2, val)) {
                    return retval;
                }
                if (val > 23) {
                    return retval;
                }
                retval.hour = val;
                retval.has_time = true;
                break;
            }
            case 'M': {
                int val;
                if (!read_int(str, pos, 1, 2, val)) {
                    return retval;
                }
                if (val > 59) {
                    return retval;
                }
                retval.minute = val;
                retval.has_time = true;
                break;
            }
            case 'S': {
                int val;
                if (!read_int(str, pos, 1, 2, val)) {
                    return retval;
                }
                if (val > 61) {
                    return retval;
                }
                retval.second = val;
                retval.has_time = true;
                break;
            }
            case 'f':
            case 'L': {
                size_t start = pos;
                int val = 0;
                while (pos < str.size() && isdigit((unsigned char) str[pos])) {
                    if (pos - start < 6) {
                        val = val * 10 + (str[pos] - '0');
                    }
                    pos += 1;
                }
                frac_digits = (int) (pos - start);
                if (frac_digits < 1) {
                    return retval;
                }
                int digits = frac_digits > 6 ? 6 : frac_digits;
                for (int lpc = digits; lpc < 6; lpc++) {
                    val *= 10;
                }
                retval.micros = val;
                break;
            }
            case 'b':
            case 'B': {
                bool found = false;
                for (int lpc = 0; lpc < 12 && !found; lpc++) {
                    size_t save = pos;
                    if (match_word(str, pos, MONTHS_LONG[lpc])) {
                        retval.month = lpc + 1;
                        found = true;
                        break;
                    }
                    pos = save;
                    if (match_word(str, pos, MONTHS[lpc])) {
                        retval.month = lpc + 1;
                        found = true;
                    }
                }
                if (!found) {
                    return retval;
                }
                break;
            }
            case 'a':
            case 'A': {
                bool found = false;
                for (const char* day : DAYS) {
                    if (match_word(str, pos, day)) {
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    return retval;
                }
                while (pos < str.size() && isalpha((unsigned char) str[pos])) {
                    pos += 1;
                }
                break;
            }
            case 'p': {
                if (match_word(str, pos, "am")) {
                    pm = 0;
                } else if (match_word(str, pos, "pm")) {
                    pm = 1;
                } else {
                    return retval;
                }
                break;
            }
            case 'z': {
                if (pos < str.size() && (str[pos] == 'Z' || str[pos] == 'z')) {
                    pos += 1;
                    retval.has_zone = true;
                    retval.zone_offset = 0;
                    break;
                }
                if (pos >= str.size() || (str[pos] != '+' && str[pos] != '-')) {
                    return retval;
                }
                int sign = str[pos] == '-' ? -1 : 1;
                pos += 1;
                int hours;
                if (!read_int(str, pos, 2, 2, hours)) {
